/**
 * Scratch page for T13 — the frame budget, measured rather than guessed.
 * Not part of the game; served at /perf.html.
 *
 * The acceptance check is "60fps on a throttled mobile profile", and the thing to
 * measure is not the frame rate a fast desktop happens to reach — that is 60 or 120
 * whatever the renderer costs, because the browser paces it. What matters is how much of
 * a 16.7 ms frame the game *spends*, and how many draw calls it takes to spend it.
 *
 * So this does not run the game's ticker. It builds the real render stack that
 * `PlayState.enter()` builds — the same `Playfield`, `TileMap`, ball sprite and `Hud`,
 * out of the same atlas — steps the simulation to a chosen tick, and then renders that
 * one frame `SAMPLES` times back to back. `renderer.render()` is synchronous up to the
 * GPU, so a batch of a few hundred is a stable cost per frame rather than a jitter
 * reading. Each level is measured twice: the whole frame, and the tile containers alone,
 * because the tile layer is what T13 asks about and what the other layers cost is not
 * its answer.
 *
 * Draw calls are counted by wrapping the WebGL context's four draw entry points before
 * Pixi ever touches it, which is the only measurement here that is not a stopwatch, and
 * the one T13 actually asks for: **one texture and one draw call for the tile layer**.
 *
 * `?level=N` starts on a level, `?ticks=N` steps it that far in before measuring
 * (default 240 — six seconds of play, so the camera has scrolled and a hazard is
 * somewhere other than its spawn), and `?wide=N` measures the widescreen band.
 */
import { Application, Container, Graphics, Sprite, Text, type Spritesheet } from 'pixi.js';

import { hdEnabled, loadSheet } from './sheet.ts';

import { PLAY_HEIGHT, VIEW_HEIGHT, VIEW_WIDTH } from '../core/Viewport.ts';
import { DYING } from '../game/Ball.ts';
import { HUD_TOP, Hud, meterTicks } from '../game/Hud.ts';
import { Level, TILE_SIZE, type LevelJson } from '../game/Level.ts';
import { KEY_RIGHT, KEY_UP } from '../game/Physics.ts';
import { Playfield } from '../game/Playfield.ts';
import { TileMap } from '../game/TileMap.ts';
import { HUD_COLOUR } from '../game/Tiles.ts';

const LEVEL_COUNT = 11;

/** Renders timed per measurement, as one batch — see `timeRenders`. */
const SAMPLES = 240;

/** Renders thrown away first, while the GPU warms up and Pixi allocates its batches. */
const WARMUP = 60;

/** Default ticks of play before measuring — long enough to be somewhere, not at spawn. */
const DEFAULT_TICKS = 240;

/** A frame at 60 Hz. The whole point of the exercise. */
const FRAME_BUDGET_MS = 1000 / 60;

/** Wrapped around the GL context: draw calls and texture binds for one `render()`. */
type GlCounters = { draws: number; textures: number };

const gl: GlCounters = { draws: 0, textures: 0 };

/**
 * Count draw calls at the source. Wrapping the prototypes catches the context Pixi makes
 * for itself, which is not reachable any other way, and costs one property lookup per
 * call — invisible against a draw.
 */
function installGlCounters(): void {
  const protos = [WebGL2RenderingContext.prototype, WebGLRenderingContext.prototype];
  const draws = ['drawElements', 'drawArrays', 'drawElementsInstanced', 'drawArraysInstanced'];
  for (const proto of protos) {
    for (const name of draws) {
      const original = (proto as unknown as Record<string, unknown>)[name];
      if (typeof original !== 'function') continue;
      (proto as unknown as Record<string, unknown>)[name] = function (
        this: WebGLRenderingContext,
        ...args: unknown[]
      ): unknown {
        gl.draws++;
        return (original as (...a: unknown[]) => unknown).apply(this, args);
      };
    }
    // The unbound method is taken in order to re-apply it with the original receiver,
    // which is the whole point of a wrapper.
    // eslint-disable-next-line @typescript-eslint/unbound-method
    const bind = proto.bindTexture as (...a: unknown[]) => unknown;
    (proto as unknown as Record<string, unknown>)['bindTexture'] = function (
      this: WebGLRenderingContext,
      ...args: unknown[]
    ): unknown {
      gl.textures++;
      return bind.apply(this, args);
    };
  }
}

type Scene = {
  field: Playfield;
  map: TileMap;
  ball: Sprite;
  hud: Hud;
  root: Container;
  margin: number;
};

type Measurement = {
  /** Milliseconds for one `render()` of the whole frame. */
  frameMs: number;
  /** Draw calls the renderer issued for the whole frame. */
  frameDraws: number;
  /** Milliseconds for the tile containers alone. */
  tileMs: number;
  /** Draw calls for the tile containers alone. This is T13's number. */
  tileDraws: number;
  /**
   * `bindTexture` calls per frame in the steady state. Pixi tracks what is bound and
   * skips a redundant bind, so with one atlas and no rebinding this settles at zero —
   * which is the strongest form of "one texture" there is.
   */
  textures: number;
  /** Sprites the tile window left visible, so the draw count has a denominator. */
  sprites: number;
  /** Tick the frame was taken at — below `ticks` if the run ended early. */
  tick: number;
};

async function loadLevel(id: number): Promise<LevelJson> {
  const name = String(id).padStart(3, '0');
  const response = await fetch(`levels/${name}.json`);
  if (!response.ok) throw new Error(`levels/${name}.json: ${response.status}`);
  return (await response.json()) as LevelJson;
}

/**
 * `PlayState.enter()`, minus the state machine and the session. Any divergence here is a
 * measurement of the wrong thing, so it is deliberately the same call sequence.
 */
function build(json: LevelJson, sheet: Spritesheet, margin: number): Scene {
  const bandWidth = VIEW_WIDTH + 2 * margin;
  const field = new Playfield(new Level(json));
  const map = new TileMap(field.level, sheet, { door: field.door, viewWidth: bandWidth });
  const ball = new Sprite();
  const hud = new Hud(sheet);
  hud.bannerText = `LEVEL ${field.level.id}`;

  const play = new Container();
  play.addChild(map.view, ball, map.front);
  const mask = new Graphics().rect(0, 0, bandWidth, PLAY_HEIGHT).fill(0xffffff);
  play.addChild(mask);
  play.mask = mask;
  play.x = -margin;

  const root = new Container();
  root.addChild(new Graphics().rect(-margin, 0, bandWidth, VIEW_HEIGHT).fill(0x000000), play);
  if (margin > 0) {
    root.addChild(
      new Graphics().rect(-margin, HUD_TOP, bandWidth, VIEW_HEIGHT - HUD_TOP).fill(HUD_COLOUR),
    );
  }
  root.addChild(hud.view);

  return { field, map, ball, hud, root, margin };
}

/** `PlayState.draw()`. Same reason as `build()`: it has to be the frame the game draws. */
function draw(scene: Scene, sheet: Spritesheet): void {
  const { field, map, ball, hud, margin } = scene;
  const camX = field.camera.x - margin;
  map.update(camX, field.camera.y);

  const dying = field.ball.state === DYING;
  const frame = dying ? 'ball_burst' : field.ball.size === 16 ? 'ball_large' : 'ball_small';
  const texture = sheet.textures[frame];
  if (texture) ball.texture = texture;
  const offset = dying ? TILE_SIZE / 2 : field.ball.radius;
  ball.position.set(field.ball.x - offset - camX, field.ball.y - offset - field.camera.y);

  hud.update({
    score: field.score,
    lives: field.lives,
    hoopsLeft: field.level.hoopCount - field.hoopsTaken,
    boostTicks: meterTicks(field.ball.speedTicks, field.ball.gravityTicks, field.ball.jumpTicks),
    bannerTicks: field.bannerTicks,
  });
}

/**
 * Run the level in for `ticks`, holding right and pulsing bounce — the same periodic
 * script `tests/ball.test.ts` uses to get a ball across a level without steering it.
 *
 * A script that steers nothing will end some levels early, so the tick actually reached
 * is returned and reported: a row measuring a frame from tick 61 is measuring a real
 * frame, but not the one the column header claims.
 */
function play(field: Playfield, ticks: number): number {
  for (let tick = 0; tick < ticks; tick++) {
    field.ball.keys = KEY_RIGHT | ((tick + 16) % 25 < 13 ? KEY_UP : 0);
    field.tick();
    if (field.gameOver || field.levelComplete) return tick + 1;
  }
  return ticks;
}

/**
 * Which tick of that run draws the most tiles.
 *
 * Timing one arbitrary tick measures whatever the ball happened to be looking at — level
 * 011 at tick 240 is a screenful of sky and no sprites at all, which is a real frame but
 * the cheapest one there is. This walks the same run, records the window's sprite count
 * each tick, and returns the fullest, so the row below is the level's worst case rather
 * than a sample of its average.
 */
function peakTick(json: LevelJson, sheet: Spritesheet, margin: number, ticks: number): number {
  const scene = build(json, sheet, margin);
  let best = 0;
  let bestCount = -1;
  for (let tick = 0; tick <= ticks; tick++) {
    draw(scene, sheet);
    const count = scene.map.spriteCount;
    if (count > bestCount) {
      bestCount = count;
      best = tick;
    }
    if (tick === ticks) break;
    scene.field.ball.keys = KEY_RIGHT | ((tick + 16) % 25 < 13 ? KEY_UP : 0);
    scene.field.tick();
    if (scene.field.gameOver || scene.field.levelComplete) break;
  }
  scene.map.destroy();
  return best;
}

/**
 * Time `SAMPLES` renders as one batch and divide.
 *
 * Timing each render separately is what a profiler wants and what this cannot have:
 * `performance.now()` is deliberately coarsened to about 100 µs in a browser (it is a
 * timing-attack surface), and a frame here costs less than that, so per-render samples
 * come back as a column of zeroes with the occasional 0.1. A batch of a few hundred is
 * long enough that the quantum is noise, and the number wanted is a mean cost per frame
 * rather than a distribution.
 */
function timeRenders(app: Application, count: number): number {
  const stage = app.stage;
  const start = performance.now();
  for (let i = 0; i < count; i++) app.renderer.render(stage);
  return (performance.now() - start) / count;
}

function measure(app: Application, scene: Scene, sheet: Spritesheet): Measurement {
  const stage = app.stage;
  draw(scene, sheet);

  // The whole frame: tiles, ball, hoop fronts, HUD.
  stage.removeChildren();
  stage.addChild(scene.root);
  timeRenders(app, WARMUP);
  gl.draws = 0;
  gl.textures = 0;
  const frameMs = timeRenders(app, SAMPLES);
  const frameDraws = gl.draws / SAMPLES;
  const textures = gl.textures / SAMPLES;

  // The tile layer alone, which is the thing T13 names. `view` is the fills, hazards and
  // back halves; `front` is the hoop halves the ball passes behind.
  const tiles = new Container();
  tiles.addChild(scene.map.view, scene.map.front);
  stage.removeChildren();
  stage.addChild(tiles);
  timeRenders(app, WARMUP);
  gl.draws = 0;
  const tileMs = timeRenders(app, SAMPLES);
  const tileDraws = gl.draws / SAMPLES;

  // The scene is destroyed straight after this returns, so the tile containers are left
  // where the second pass put them rather than reparented back into a dead tree.
  return {
    frameMs,
    frameDraws,
    tileMs,
    tileDraws,
    textures,
    sprites: scene.map.spriteCount,
    tick: scene.field.ticks,
  };
}

function row(id: number, m: Measurement): string {
  const pad = (value: string, width: number): string => value.padStart(width);
  return [
    pad(String(id).padStart(3, '0'), 3),
    pad(m.tick.toFixed(0), 5),
    pad(m.sprites.toFixed(0), 7),
    pad(m.tileMs.toFixed(3), 8),
    pad(m.tileDraws.toFixed(1), 6),
    pad(m.frameMs.toFixed(3), 9),
    pad(m.frameDraws.toFixed(1), 6),
    pad(m.textures.toFixed(1), 5),
    pad(`${((m.frameMs / FRAME_BUDGET_MS) * 100).toFixed(2)}%`, 8),
  ].join('  ');
}

async function main(): Promise<void> {
  installGlCounters();

  const params = new URLSearchParams(window.location.search);
  const ticks = Number(params.get('ticks') ?? DEFAULT_TICKS);
  const margin = Number(params.get('wide') ?? 0) * TILE_SIZE;
  const only = params.get('level');

  const canvas = document.getElementById('perf-canvas') as HTMLCanvasElement;
  const app = new Application();
  await app.init({
    canvas,
    background: 0x14141a,
    width: VIEW_WIDTH + 2 * margin,
    height: VIEW_HEIGHT,
    antialias: false,
    roundPixels: true,
  });

  // SD by default: these numbers are T13's baseline, and H6 is what re-measures them
  // against the HD sheet. `?hd=1` runs the comparison early.
  const sheet: Spritesheet = await loadSheet(hdEnabled(false));

  const out = document.getElementById('report')!;
  const lines: string[] = [
    `${SAMPLES} renders per level, of the busiest frame in the first ${ticks} ticks` +
      (margin > 0 ? `, widescreen +${margin}px each side` : ''),
    '',
    '                    tile layer          whole frame',
    'lvl   tick  sprites      ms  draws         ms  draws  texs   budget',
    '---  -----  -------  ------  -----  ---------  -----  ----  -------',
  ];
  const report = (): void => {
    out.textContent = lines.join('\n');
  };
  report();

  const ids = only ? [Number(only)] : Array.from({ length: LEVEL_COUNT }, (_, i) => i + 1);
  const worst = { frameMs: 0, frameDraws: 0, tileDraws: 0, textures: 0, sprites: 0 };

  for (const id of ids) {
    const json = await loadLevel(id);
    const scene = build(json, sheet, margin);
    play(scene.field, peakTick(json, sheet, margin, ticks));
    const m = measure(app, scene, sheet);
    lines.push(row(id, m));
    report();
    worst.frameMs = Math.max(worst.frameMs, m.frameMs);
    worst.frameDraws = Math.max(worst.frameDraws, m.frameDraws);
    worst.tileDraws = Math.max(worst.tileDraws, m.tileDraws);
    worst.textures = Math.max(worst.textures, m.textures);
    worst.sprites = Math.max(worst.sprites, m.sprites);
    // Yield so the report paints a row at a time rather than all at the end.
    await new Promise((resolve) => setTimeout(resolve, 0));
    scene.map.destroy();
  }

  lines.push(
    '',
    `worst frame   ${worst.frameMs.toFixed(3)} ms — ` +
      `${((worst.frameMs / FRAME_BUDGET_MS) * 100).toFixed(2)}% of a 60Hz frame, ` +
      `${worst.frameDraws.toFixed(0)} draw calls`,
    `worst tiles   ${worst.tileDraws.toFixed(0)} draw calls for up to ` +
      `${worst.sprites.toFixed(0)} sprites, ${worst.textures.toFixed(0)} texture binds a frame`,
    '',
    'A mid-range phone is several times slower than a desktop, so a frame here wants to',
    'be a small fraction of the budget for 60fps to survive the throttle.',
  );
  report();

  // Leave a real frame on the canvas. The measured scenes are torn down as they go, and
  // a blank canvas over a page of timings invites the reasonable question of whether
  // anything was drawn at all.
  const firstId = ids[0] ?? 1;
  const firstJson = await loadLevel(firstId);
  const shown = build(firstJson, sheet, margin);
  play(shown.field, peakTick(firstJson, sheet, margin, ticks));
  draw(shown, sheet);
  app.stage.removeChildren();
  app.stage.addChild(shown.root);
  const note = new Text({
    text: 'level ' + String(shown.field.level.id) + ' — the frame the first row timed',
    style: { fill: 0x6a6a78, fontFamily: 'monospace', fontSize: 6 },
  });
  note.position.set(2, 2);
  app.stage.addChild(note);
  app.renderer.render(app.stage);
}

void main();
